insert into section_rich_text (section_id,body_text) values ('sec_dockside_about','Climb aboard with a small group and get ready to fly! You will be safely harnessed in before the boat gently picks up speed, lifting you smoothly into the sky. Soar up to 400 feet above the Gulf of Mexico and take in breathtaking views of sugar-white beaches, crystal-clear turquoise water, marine life, and miles of coastline in every direction. Each flight lasts 8–10 minutes and is available for single, double, or triple riders. It''s peaceful, thrilling, and unforgettable. Perfect for first timers and adventure lovers alike!');
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_highlights','✦ Enjoy panoramic views of the Gulf Coast on an Orange Beach: Dockside Parasail experience',1);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_highlights','✦ Soar up to 400 feet above the Gulf of Mexico with an 8–10-minute flight time',2);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_highlights','✦ Small group boat experience that is safe and perfect for first timers',3);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_highlights','✦ Single, double, or triple flights available',4);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_highlights','✦ Perfect for ages 5+',5);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_restrictions','Participants must be at least 5 years old or older to ride on the boat or parasail.',1);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_restrictions','The combined weight of guests flying must be between 150 and 450 pounds.',2);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_restrictions','Children under 14 years old must be accompanied on the parasail boat by a guest who is 16 years old or older.',3);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_restrictions','For guests under the age of 19, a parent or legal guardian is required to sign a waiver. Guests 19 years of age or older may sign their own waiver.',4);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_restrictions','Electronics and shoes are not permitted on the boat. These items may be safely left with a team member at the beach.',5);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_restrictions','Expectant mothers are not permitted.',6);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_restrictions','There is a maximum of 2 observers.',7);
insert into section_bullets (section_id,bullet_text,sort_order) values ('sec_dockside_restrictions','This departure location allows guests to step directly onto the vessel. There is a place for guests to leave their wheelchairs/walkers/scooters at the dock during the excursion.',8);
